INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (1, 'p0000001-0000-4000-8000-000000000000', 1, 'Tai Nghe Bluetooth Chống Ồn Wireless Pro X', 'tai-nghe-bluetooth-chong-on-wireless-pro-x', 'Tai nghe Bluetooth chống ồn chủ động (ANC) tiên tiến, chất âm Hi-Res chân thực, thời lượng pin đến 30h liên tục.', 'Tai Nghe Bluetooth Chống Ồn Wireless Pro X là dòng sản phẩm tai nghe không dây cao cấp dành cho tín đồ âm nhạc và công việc bận rộn.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (2, 'p0000002-0000-4000-8000-000000000000', 1, 'Bàn Phím Cơ Cơ Học RGB Gaming K87', 'ban-phim-co-co-hoc-rgb-gaming-k87', 'Bàn phím cơ Gaming K87 bố cục 87 phím gọn gàng, hệ thống đèn RGB 16.8 triệu màu linh hoạt và switch cơ học siêu bền.', 'Bàn Phím Cơ Cơ Học RGB Gaming K87 là lựa chọn hoàn hảo cho các gamer chuyên nghiệp và nhân viên văn phòng yêu thích trải nghiệm gõ phím chân thực.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (3, 'p0000003-0000-4000-8000-000000000000', 2, 'Áo Sơ Mi Nam Form Rộng Unisex Style Hàn Quốc', 'ao-so-mi-nam-form-rong-unisex-style-han-quoc', 'Áo sơ mi nam form rộng phong cách Hàn Quốc trẻ trung, chất liệu cotton lụa mềm mịn, thoáng mát và chống nhăn hiệu quả.', 'Áo Sơ Mi Nam Form Rộng Unisex Style Hàn Quốc mang lại vẻ ngoài lịch lãm, hiện đại nhưng không kém phần thoải mái năng động.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (4, 'p0000004-0000-4000-8000-000000000000', 2, 'Quần Jeans Nam Ống Rộng Wide Leg Denim', 'quan-jeans-nam-ong-rong-wide-leg-denim', 'Quần Jeans nam ống rộng dáng Wide Leg Denim cá tính, chất vải bò dày dặn, bền màu và tạo form cực chuẩn.', 'Quần Jeans Nam Ống Rộng Wide Leg Denim là item thời trang không thể thiếu trong tủ đồ của các bạn trẻ yêu thích sự tự do, phong cách.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (5, 'p0000005-0000-4000-8000-000000000000', 3, 'Serum Dưỡng Sáng Đều Màu Da Vitamin C 15%', 'serum-duong-sang-deu-mau-da-vitamin-c-15', 'Serum Vitamin C 15% dưỡng sáng da, mờ thâm mụn, đều màu da và hỗ trợ chống oxy hóa mạnh mẽ.', 'Serum Dưỡng Sáng Đều Màu Da Vitamin C 15% là giải pháp chăm sóc da chuyên sâu giúp khôi phục vẻ rạng rỡ tươi trẻ cho làn da.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (6, 'p0000006-0000-4000-8000-000000000000', 4, 'Nồi Chiên Không Dầu Điện Tử 6.5L Sunhouse', 'noi-chien-khong-dau-dien-tu-65l-sunhouse', 'Nồi chiên không dầu điện tử 6.5L Sunhouse công nghệ Rapid Air chiên nướng giòn ngon, giảm 85% lượng dầu mỡ thừa.', 'Nồi Chiên Không Dầu Điện Tử 6.5L Sunhouse mang đến giải pháp nấu nướng tiện lợi, an toàn cho sức khỏe cả gia đình.
INSERT INTO products (id, public_id, seller_id, name, slug, short_description, description, brand, origin, warranty_info, status, average_rating, review_count, sold_count, variant_options, created_at) VALUES (7, 'p0000007-0000-4000-8000-000000000000', 5, 'Tã Bỉm Dán/Quần Cao Cấp Ultra Soft Cho Bé', 'ta-bim-dan-quan-cao-cap-ultra-soft-cho-be', 'Tã bỉm dán/quần cao cấp Ultra Soft siêu mỏng nhẹ, khả năng thấm hút vượt trội chống tràn 12h cho bé ngủ ngon.', 'Tã Bỉm Dán/Quần Cao Cấp Ultra Soft Cho Bé được thiết kế chuyên biệt nhằm chăm sóc làn da nhạy cảm nhất của trẻ nhỏ.
