INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (365, 31, 3, 590, 5, 'Áo sơ mi đẹp lắm, chất cotton lụa mềm mát. Form rộng vừa vặn, mặc thoải mái. Đường may tỉ mỉ, khuy áo chắc chắn. Mình 1m70, 60kg mặc size M vừa đẹp.', '2026-03-15 13:24:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (366, 24, 3, 597, 4, 'Chất vải mềm, thấm mồ hôi tốt. Kiểu dáng Hàn Quốc rất hợp xu hướng. Chỉ trừ 1 sao vì giặt lần đầu hơi ra màu nhẹ, nhưng các lần sau thì ổn.', '2026-01-15 18:38:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (367, 65, 14, 604, 5, 'Mèo nhà mình rất thích loại hạt này! Từ ngày đổi sang Royal Canin, lông bé mượt hơn, ăn ngon hơn hẳn. Bao bì kín, hạt không bị ẩm. Sẽ mua tiếp hàng tháng!', '2026-02-19 22:04:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (368, 69, 24, 642, 5, 'Shop tư vấn rất tận tâm, giúp mình chọn đúng sản phẩm phù hợp. Nhận hàng về dùng thử thì quá ưng ý. Chất lượng đúng như shop cam kết, 5 sao không cần suy nghĩ!', '2026-01-21 21:48:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (369, 74, 17, 588, 5, 'Wow, không ngờ với giá này mà chất lượng tốt đến vậy! Mình đã mua ở nhiều shop khác nhau nhưng shop này là tốt nhất. Sản phẩm đúng mô tả, màu sắc đẹp, chất liệu bền.', '2026-02-28 20:42:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (370, 69, 1, 712, 5, 'Tai nghe chống ồn cực đỉnh! ANC hoạt động rất hiệu quả, bật lên là gần như cách âm hoàn toàn với môi trường xung quanh. Chất âm Hi-Res trong trẻo, bass sâu. Pin 30h xài cả tuần!', '2026-05-22 12:30:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (371, 28, 1, 586, 4, 'Tai nghe tốt, chống ồn khá hiệu quả. Âm thanh chất lượng, bass mạnh mẽ. Đệm tai êm, đeo lâu không đau. Trừ 1 sao vì kết nối bluetooth đôi khi hơi chậm khi chuyển thiết bị.', '2026-03-18 22:58:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (372, 67, 14, 676, 4, 'Hạt chất lượng, mèo ăn ngon miệng. Gói 2kg đủ dùng cho 1 bé trong 1 tháng. Hạn sử dụng còn lâu. Chỉ trừ 1 sao vì giá có hơi cao so với mua ở siêu thị.', '2026-02-18 13:58:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (373, 32, 6, 705, 5, 'Nồi chiên không dầu này thật sự xuất sắc! Dung tích 6.5L vừa đủ cho gia đình 4 người. Chiên khoai tây, sườn nướng đều giòn đều. Bảng điều khiển cảm ứng dễ dùng, vệ sinh lòng nồi cũng rất tiện.', '2026-07-24 12:59:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (374, 60, 18, 675, 5, 'Đặt hàng 3 cái cho cả nhà dùng, ai cũng thích. Giá mua nhiều còn được giảm thêm, shop rất chiều khách. Sản phẩm xứng đáng best seller, chất lượng đỉnh cao!', '2026-02-12 20:07:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (375, 68, 18, 605, 2, 'Giao hàng rất chậm, đợi gần 1 tuần mới nhận. Sản phẩm thì chất lượng tạm, không đáng với giá tiền bỏ ra. Hơi hối hận khi mua, mong shop cải thiện.', '2026-05-28 21:30:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (376, 22, 5, 647, 5, 'Serum Vitamin C này amazing! Dùng 3 tuần thấy da sáng hơn rõ rệt, vết thâm mụn mờ đi nhiều. Kết cấu mỏng nhẹ, thấm nhanh không bết dính. Da mình dầu mà dùng vẫn ok!', '2026-07-21 20:38:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (377, 68, 21, 696, 4, 'Hàng chất lượng, giá hợp lý. Mình dùng được khoảng 3 tuần rồi, vẫn rất ổn. Chỉ tiếc là không có thêm phụ kiện đi kèm. Nhưng nhìn chung vẫn recommend nhé!', '2026-01-24 12:25:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (378, 57, 22, 583, 5, 'Áo khoác gió chống nước rất tốt, đi mưa nhỏ hoàn toàn không thấm. Thiết kế unisex đẹp, phù hợp nam nữ. Chất liệu nhẹ mà giữ ấm ok. Mặc đi du lịch rất tiện!', '2026-07-27 17:20:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (379, 23, 15, 652, 4, 'Lần đầu mua ở shop, sản phẩm khá tốt. Chất liệu đẹp, thiết kế hợp thời trang. Có điểm nhỏ là hướng dẫn sử dụng hơi khó hiểu nhưng youtube có hướng dẫn nên ok.', '2026-06-28 15:29:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (380, 58, 20, 695, 3, 'Sản phẩm tạm được, không quá nổi bật nhưng cũng không tệ. Chất lượng trung bình khá ở tầm giá này. Đóng gói hơi sơ sài, may mà hàng không bị hư. Tạm chấp nhận.', '2026-01-18 19:22:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (381, 68, 13, 654, 5, 'Đồng hồ rất đẹp, dây da thật mềm mại. Mặt chronograph sang trọng, kim giây chạy mượt. Đeo tay rất vừa vặn, phù hợp cả mặc vest hay casual. Hộp đựng cũng rất đẹp.', '2026-07-28 13:23:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (382, 61, 17, 562, 5, 'Mình là khách quen của shop, mỗi lần mua đều rất yên tâm về chất lượng. Lần này sản phẩm cũng không ngoại lệ, dùng cực kỳ tốt. Cảm ơn shop nhé!', '2026-04-14 16:29:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (383, 56, 13, 630, 4, 'Đồng hồ chất lượng tốt ở tầm giá này. Dây da mềm, đeo thoải mái. Mặt đồng hồ rõ nét, dạ quang yếu. Chống nước 3ATM, đeo rửa tay bình thường không sao.', '2026-03-28 21:46:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (384, 63, 21, 633, 5, 'Đây là lần thứ 3 mình mua ở shop rồi, lần nào cũng hài lòng. Sản phẩm chất lượng ổn định, giá hợp lý. Shop gói hàng rất kỹ, có thêm quà tặng nhỏ nữa, rất tâm lý!', '2026-07-14 21:53:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (385, 21, 18, 686, 3, 'Giao hàng chậm 3 ngày, sản phẩm thì chất lượng trung bình. Dùng được nhưng không quá ấn tượng. Giá thì ok nhưng mình nghĩ có thể cải thiện thêm về chất liệu.', '2026-06-14 12:23:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (386, 74, 3, 713, 5, 'Áo mặc đi làm cực sang, ai cũng hỏi mua ở đâu. Phối với quần tây hay jeans đều đẹp. Shop gói hàng cẩn thận, có kèm túi đựng riêng. Sẽ mua thêm màu khác!', '2026-06-28 15:02:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (387, 27, 7, 699, 5, 'Tã bỉm mềm mại, bé nhà mình mặc cả đêm không bị hăm hay đỏ da. Thấm hút tốt, không bị tràn. Đai hông co giãn vừa vặn. Bé 8 tháng dùng size M vừa in.', '2026-02-28 22:14:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (388, 19, 8, 643, 5, 'Bộ nồi inox chất lượng cao, đáy 3 lớp truyền nhiệt rất nhanh và đều. Nấu cơm, kho thịt, hầm xương đều xuất sắc. Nắp kính trong suốt rất tiện quan sát khi nấu.', '2026-06-23 11:01:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (389, 57, 10, 672, 5, 'Sách hay quá! Nội dung kinh điển, ai cũng nên đọc ít nhất 1 lần. In ấn đẹp, giấy trắng, font chữ rõ ràng. Ship nhanh, đóng gói kỹ, sách không bị cong góc.', '2026-02-18 17:59:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (390, 74, 5, 613, 4, 'Dùng được 2 tuần, thấy da đều màu hơn. Vết thâm mờ dần nhưng chưa hết hẳn. Cần kiên trì dùng thêm. Serum thấm tốt, không gây kích ứng cho da nhạy cảm của mình.', '2026-04-28 18:46:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (391, 21, 7, 719, 5, 'Mẹ bỉm decree: đây là loại tã tốt nhất mình từng dùng cho con! Siêu mỏng nhẹ, bé thoải mái vận động. Thấm hút cực tốt, cả đêm không tràn. Giá cũng hợp lý.', '2026-03-19 13:09:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (392, 23, 1, 651, 5, 'Best tai nghe mình từng dùng! Chống ồn ANC cực mạnh, dùng ở văn phòng hay trên máy bay đều ok. Pin trâu, sạc nhanh. Micro đàm thoại rõ ràng. Đáng mua lắm!', '2026-06-28 14:14:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (393, 75, 6, 624, 5, 'Mua nồi chiên này được 1 tháng rồi, gần như ngày nào cũng dùng. Chiên gà, nướng bánh, làm khoai lang nướng đều ngon cả. Tiết kiệm dầu ăn rất nhiều, cả nhà ai cũng thích!', '2026-03-28 18:53:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (394, 23, 3, 649, 4, 'Chất áo tốt, form đẹp. Mặc không nhăn nhiều, giặt máy được. Cổ áo cứng cáp, giữ form tốt. Giá hơi cao so với áo sơ mi bình thường nhưng chất lượng xứng đáng.', '2026-07-11 16:35:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (395, 27, 3, 577, 4, 'Giao hàng hơi chậm so với dự kiến (trễ 1 ngày) nhưng sản phẩm thì rất tốt, đúng như quảng cáo. Chất liệu bền đẹp, dùng thấy thích. Trừ 1 sao vì ship chậm thôi.', '2026-01-28 19:21:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (396, 66, 22, 611, 4, 'Áo đẹp, chất liệu tốt. Chống nước hiệu quả, gió thổi không lọt qua. Có mũ trùm đầu tiện lợi. Chỉ trừ 1 sao vì túi khóa kéo hơi nhỏ, để điện thoại to thì chật.', '2026-07-25 21:52:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (397, 77, 8, 657, 4, 'Nồi đẹp, sang trọng. Inox 304 sáng bóng, dùng được trên bếp từ. Quai cầm cách nhiệt tốt. Chỉ trừ 1 sao vì nồi nhỏ nhất hơi cạn, nấu canh cho 4 người thì hơi ít.', '2026-07-14 20:41:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (398, 24, 10, 661, 4, 'Nội dung sách rất hay, bổ ích. Bản dịch tiếng Việt lưu loát, dễ hiểu. In ấn chất lượng tốt. Chỉ trừ 1 sao vì bìa mềm hơi mỏng, sợ dùng lâu sẽ bị xù.', '2026-04-23 16:29:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (399, 27, 9, 708, 5, 'Thảm yoga rất êm, độ bám tốt. Dày 8mm bảo vệ đầu gối khi tập các tư thế quỳ. Mặt trên không trơn khi đổ mồ hôi. Cuộn gọn dễ dàng, có túi đựng tiện lợi.', '2026-05-10 20:50:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (400, 34, 6, 681, 4, 'Nồi chiên hoạt động tốt, chiên đồ ăn giòn ngon. Chỉ có điều tiếng ồn khi quạt chạy hơi to một chút, nhưng trong phạm vi chấp nhận được. Dung tích lớn, đủ chiên nguyên con gà 2kg.', '2026-05-23 11:08:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (401, 34, 20, 645, 4, 'Nhận hàng rồi, đóng gói chắc chắn. Sản phẩm dùng tốt, đúng hình. Có 1 vết xước rất nhỏ ở góc nhưng không đáng kể lắm, không ảnh hưởng đến sử dụng. Tổng thể ok.', '2026-06-28 17:31:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (402, 63, 9, 606, 4, 'Thảm chất lượng ok, đàn hồi tốt. Chống trượt 2 mặt, tập yoga rất an toàn. Không mùi như một số thảm giá rẻ. Chỉ hơi nặng một chút khi mang đi studio.', '2026-04-14 17:41:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (403, 80, 7, 710, 4, 'Tã mềm, thấm hút tốt. Bé dùng không bị kích ứng da. Chỉ trừ 1 sao vì miếng dán đôi khi không bám chắc lắm, bé hay lật lẫy thì bỉm hơi bị lệch.', '2026-05-19 17:02:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (404, 56, 5, 575, 5, 'Mình đã thử nhiều serum vitamin C và đây là chai mình thích nhất! Nồng độ 15% vừa đủ hiệu quả mà không gây kích ứng. Da sáng tone rõ rệt sau 1 tháng sử dụng.', '2026-05-23 22:42:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (405, 29, 6, 636, 5, 'Tuyệt vời! Từ khi có nồi chiên này, mình ít ăn đồ chiên dầu hơn hẳn. Sức khỏe cải thiện nhiều. Nồi nóng đều, thức ăn chín đều từ trong ra ngoài, giòn tan mà không cần dầu.', '2026-03-15 21:00:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (406, 26, 14, 663, 5, 'Đặt hàng cho 3 bé mèo ở nhà, bé nào cũng thích. Hạt Royal Canin chất lượng, đảm bảo dinh dưỡng cho mèo. Ship nhanh, đóng gói kỹ, hàng chính hãng 100%.', '2026-05-28 11:53:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (407, 77, 22, 564, 5, 'Áo khoác gió xịn thật sự! Nhẹ như không mà chống nước, chống gió cực tốt. Phom dáng đẹp, mặc vừa vặn. Mình đặt 2 cái cho vợ chồng đi phượt, rất ưng ý!', '2026-06-28 12:04:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (408, 78, 18, 637, 4, 'Sản phẩm ổn, dùng được. Đóng gói cẩn thận, giao đúng hẹn. Trừ 1 sao vì màu sắc thực tế hơi khác so với hình trên web nhưng vẫn chấp nhận được. Nhìn chung hài lòng.', '2026-05-19 11:00:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (409, 61, 13, 690, 5, 'Mua tặng bạn trai, bạn ấy rất thích! Đồng hồ trông sang trọng, đẳng cấp. Dây da có mùi thơm nhẹ của da thật. Chronograph hoạt động chính xác. Rất đáng mua!', '2026-01-09 17:29:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (410, 25, 9, 653, 5, 'Thảm tập yoga tuyệt vời! TPE an toàn, không mùi, không gây dị ứng da. Dày 8mm rất êm, bảo vệ cột sống tốt. Mình tập yoga 3 năm rồi, đây là thảm ưng ý nhất!', '2026-05-13 09:39:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (411, 24, 5, 660, 3, 'Serum dùng tạm ổn, có thấy da sáng hơn một chút nhưng chưa rõ rệt lắm. Có thể do da mình khó tính. Kết cấu thì ok, thấm nhanh. Sẽ dùng hết chai rồi đánh giá lại.', '2026-02-25 19:59:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (412, 63, 5, 598, 4, 'Sản phẩm tốt, da mình cải thiện sau 2 tuần dùng. Thâm mụn mờ đi, da đều màu hơn. Chỉ tiếc là dung tích hơi ít, dùng khá nhanh hết. Mong shop có size lớn hơn.', '2026-07-28 16:42:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (413, 61, 8, 607, 5, 'Đầu tư bộ nồi này quá đáng giá! Dùng 2 tháng rồi, nồi vẫn sáng bóng như mới. Nấu ăn nhanh hơn hẳn so với nồi cũ, tiết kiệm gas và điện. Highly recommend!', '2026-07-11 09:00:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (414, 75, 15, 572, 4, 'Sản phẩm tốt, đúng mô tả. Chất lượng 4/5 vì có vài chi tiết nhỏ chưa hoàn hảo lắm nhưng nhìn chung rất đáng mua ở tầm giá này. Ship nhanh, đóng gói cẩn thận.', '2026-07-28 17:26:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (415, 20, 8, 664, 4, 'Bộ nồi chắc chắn, nặng tay. Chất lượng inox tốt, không bị ố vàng sau khi dùng. Nắp kính chịu nhiệt, vệ sinh dễ dàng. Giá hơi cao nhưng xứng đáng.', '2026-05-16 09:33:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (416, 72, 2, 693, 5, 'Review chân thật nhé: sản phẩm rất đáng mua! Thiết kế đẹp, vật liệu chắc chắn, dùng lâu bền. So với giá thì quá hời luôn. Ai đang phân vân thì cứ mạnh dạn đặt nhé!', '2026-06-20 13:34:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (417, 60, 22, 631, 3, 'Sản phẩm đúng mô tả nhưng chất lượng thực tế chỉ ở mức trung bình. Mình đã dùng sản phẩm tương tự của hãng khác tốt hơn một chút. Tuy nhiên giá cả cũng hợp lý.', '2026-07-14 09:32:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (418, 63, 20, 632, 2, 'Hàng nhận được bị móp hộp, sản phẩm bên trong tuy không hư nhưng có vết trầy xước nhẹ. Chất lượng không như quảng cáo, hơi thất vọng. Đóng gói cần cải thiện nhiều.', '2026-07-18 19:27:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (419, 68, 1, 608, 4, 'Tai nghe đẹp, chất âm hay. ANC chống ồn tốt ở mức trung bình-cao. Thiết kế nhẹ, đeo cả ngày không mỏi tai. Chỉ mong có thêm nhiều màu sắc hơn để lựa chọn.', '2026-06-28 10:58:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (420, 22, 14, 617, 4, 'Sản phẩm tốt, giao nhanh. Chất lượng khá ổn cho mức giá này. Mình mua để dùng hàng ngày thì rất phù hợp. Shop tư vấn vui vẻ, rep nhanh. Sẽ mua thêm lần sau.', '2026-07-20 17:09:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (421, 65, 22, 679, 5, 'Quá tuyệt vời! Mình đã tìm sản phẩm này rất lâu rồi và cuối cùng cũng tìm được shop bán chính hãng với giá tốt nhất. Hàng chuẩn, giao nhanh, đóng gói đẹp. 10 điểm!', '2026-01-18 12:39:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (422, 71, 4, 677, 5, 'Quần jeans rất đẹp, dáng wide leg chuẩn form. Vải denim dày dặn, đường may chắc chắn. Mình 1m75, 65kg mặc size L vừa khít. Phối với áo thun trắng cực chất!', '2026-02-28 13:52:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (423, 79, 3, 585, 4, 'Hàng ok, chất lượng tương xứng giá tiền. Mình đã mua sản phẩm tương tự ở shop khác với giá cao hơn mà chất lượng cũng chỉ bằng hoặc kém hơn. Sẽ mua lại.', '2026-02-28 13:50:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (424, 34, 1, 601, 4, 'Sản phẩm khá ổn so với giá tiền. Dùng được 1 tuần thấy ưng ý. Có vài điểm nhỏ có thể cải thiện thêm nhưng tổng thể rất đáng mua. Shop phục vụ nhiệt tình.', '2026-04-28 10:23:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (425, 64, 20, 714, 3, 'Hàng nhận được hơi khác so với hình trên web. Màu sắc không giống lắm, chất liệu cũng bình thường thôi. Không đến mức tệ nhưng mình kỳ vọng nhiều hơn thế. Tạm ổn.', '2026-06-12 16:36:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (426, 21, 3, 687, 2, 'Sản phẩm khác xa so với hình ảnh quảng cáo. Chất liệu mỏng và kém hơn nhiều so với mong đợi. Mình đã liên hệ shop nhưng chưa được giải quyết thỏa đáng. Thất vọng.', '2026-05-22 20:14:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (427, 29, 9, 621, 4, 'Chất lượng sản phẩm tốt hơn mình nghĩ. Giá cả hợp lý, ship cũng nhanh. Trừ 1 sao vì mình thấy nên có thêm size/màu để lựa chọn. Còn lại thì rất hài lòng.', '2026-01-15 19:52:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (428, 27, 3, 641, 4, 'Nhìn chung hài lòng với sản phẩm. Chất liệu ok, thiết kế đẹp. Chỉ trừ 1 sao vì hộp bị bẹp nhẹ khi giao nhưng sản phẩm bên trong vẫn nguyên vẹn, không ảnh hưởng.', '2026-02-09 19:54:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (429, 34, 15, 602, 5, 'Sản phẩm đúng chuẩn mô tả, chất lượng hoàn hảo. Mình đã so sánh giá ở nhiều nơi và shop này có giá tốt nhất mà vẫn đảm bảo chính hãng. Rất tin tưởng shop!', '2026-04-28 21:02:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (430, 80, 15, 634, 1, 'Hàng giả, kém chất lượng. Hoàn toàn không giống mô tả. Mình đã gửi yêu cầu hoàn tiền. Mọi người cẩn thận khi mua ở shop này, check kỹ trước khi nhận hàng.', '2026-03-24 15:24:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (431, 59, 9, 697, 3, 'Mua lần đầu thấy tạm ổn. Sản phẩm không tệ nhưng cũng không xuất sắc gì. Đóng gói bình thường, ship hơi lâu. Nếu giá rẻ hơn chút thì sẽ hài lòng hơn.', '2026-02-28 17:30:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (432, 80, 3, 570, 5, 'Lần đầu mua ở shop này và cực kỳ ấn tượng. Từ khâu đóng gói đến chất lượng sản phẩm đều hoàn hảo. Giao hàng đúng hẹn, shipper thân thiện. Sẽ giới thiệu cho bạn bè mua nữa.', '2026-06-27 19:00:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (433, 21, 6, 592, 4, 'Nồi dùng tốt, nhiệt độ ổn định. Chiên cánh gà, khoai tây rất giòn. Lòng nồi chống dính tốt, dễ rửa. Trừ 1 sao vì dây điện hơi ngắn, phải kê gần ổ cắm.', '2026-06-28 11:05:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (434, 71, 1, 674, 5, 'Mình đã dùng được gần 2 tuần rồi và rất hài lòng. Chất lượng sản phẩm vượt xa kỳ vọng so với mức giá này. Đóng gói cẩn thận, ship nhanh trong 2 ngày. Chắc chắn sẽ quay lại mua tiếp!', '2026-03-28 22:27:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (435, 31, 1, 711, 1, 'Rất thất vọng! Sản phẩm nhận được bị lỗi, không hoạt động đúng chức năng. Liên hệ shop xin đổi trả nhưng phản hồi rất chậm. Không recommend shop này cho ai cả.', '2026-02-27 21:21:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (436, 79, 15, 625, 4, 'Mua lần 2 rồi, chất lượng vẫn ổn định. Sản phẩm đúng mô tả, không có gì phải phàn nàn nhiều. Chỉ mong ship nhanh hơn xíu thì perfect. Cảm ơn shop!', '2026-03-28 22:06:00');
