INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (464, 24, 8, 721, 3, 'Giao hàng chậm 3 ngày, sản phẩm thì chất lượng trung bình. Dùng được nhưng không quá ấn tượng. Giá thì ok nhưng mình nghĩ có thể cải thiện thêm về chất liệu.', '2026-01-18 10:01:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (465, 62, 8, 665, 5, 'Mua làm quà tặng sinh nhật cho người thân, mở hộp ra ai cũng khen đẹp. Chất lượng premium, đóng gói sang trọng. Shop còn viết thiệp chúc mừng nữa, cảm động quá!', '2026-05-11 17:05:00');
INSERT INTO product_reviews (id, user_id, product_id, order_item_id, rating, comment, created_at) VALUES (466, 77, 6, 658, 4, 'Sản phẩm khá ổn so với giá tiền. Dùng được 1 tuần thấy ưng ý. Có vài điểm nhỏ có thể cải thiện thêm nhưng tổng thể rất đáng mua. Shop phục vụ nhiệt tình.', '2026-07-13 09:18:00');
