-- ADDITIONAL PRODUCT_REVIEWS (ID 365-494)

-- SYNC PRODUCT STATISTICS (average_rating, review_count, sold_count)
UPDATE products p SET 
  p.review_count = (SELECT COUNT(*) FROM product_reviews pr WHERE pr.product_id = p.id),
  p.average_rating = COALESCE((SELECT ROUND(AVG(pr.rating), 2) FROM product_reviews pr WHERE pr.product_id = p.id), 0),
  p.sold_count = COALESCE((
    SELECT SUM(oi.quantity) 
    FROM order_items oi 
    JOIN orders o ON o.id = oi.order_id 
    WHERE oi.product_id = p.id AND o.order_status IN ('COMPLETED', 'SHIPPING', 'READY_TO_SHIP')
  ), 0);

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
